// Isolated fixture only: real HTTP/database/UI, recorded provider responses.
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const fs = require('node:fs'), assert = require('node:assert/strict');
const base = 'http://127.0.0.1:8190', out = process.env.DREAMLAYER_BROWSER_EVIDENCE || 'qa/inline-mentions';
fs.mkdirSync(out, { recursive: true });
let browser, page, context;
const errors = [], checks = [], f = () => page.frameLocator('#dreamlayer-shell iframe');
const pass = name => { checks.push(name); console.log('PASS', name); };
const search = async () => {
    await f().getByLabel('Search by name or SKU').fill('ABLO-00');
    await f().getByRole('button', { name: 'Search', exact: true }).click();
    await f().getByRole('button', { name: 'Select ABLO-001 image 1', exact: true }).waitFor();
};
const pick = async numbers => {
    await search();
    for (const n of numbers) await f().getByRole('button', { name: `Select ABLO-00${n} image 1`, exact: true }).click();
    await f().getByRole('button', { name: 'Use selected images' }).click();
};
const send = async message => {
    await f().locator('#message').fill(message);
    const pending = page.waitForResponse(r => r.url().endsWith('/editor/messages') && r.request().method() === 'POST');
    await f().locator('#send').click();
    const response = await pending;
    assert.equal(response.status(), 200, await response.text());
    return { input: response.request().postDataJSON(), data: await response.json() };
};
const ready = async count => {
    await f().locator('.result-image').nth(count - 1).waitFor({ timeout: 180000 });
    await f().locator('[data-refine]').nth(count - 1).waitFor();
};
const attach = async () => { page = await context.newPage(); page.setDefaultTimeout(45000); page.on('pageerror', e => errors.push(e.message)); };
(async () => {
    browser = await chromium.launch({ headless: true });
    context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, permissions: ['clipboard-read', 'clipboard-write'] });
    await attach();
    await page.goto(base + '/admin/login');
    await page.locator('[name=email]').fill('marketplace-test@example.test');
    await page.locator('[name=password]').fill('Local-Test-2026');
    await page.getByRole('button', { name: 'Sign In', exact: true }).click();
    await page.waitForURL('**/dashboard');
    await page.goto(base + '/admin/dreamlayer/choose');
    const input = () => f().locator('#message');
    await input().fill('Please edit  on a blue background.');
    await input().evaluate(n => n.setSelectionRange(12, 12));
    await input().press('@');
    await pick([1, 2]);
    assert.equal(await input().inputValue(), 'Please edit @Asset-1 @Asset-2 on a blue background.');
    assert.deepEqual(await f().locator('#message-highlight .image-reference').allTextContents(), ['@Asset-1', '@Asset-2']);
    assert.match(await f().locator('.source-chip').nth(0).innerText(), /@Asset-1 · ABLO-001/);
    assert.match(await f().locator('.source-chip').nth(1).innerText(), /@Asset-2 · ABLO-002/);
    pass('Typing @ inserts two references at the cursor, keeps surrounding text and labels their product thumbnails');
    await input().fill('I want  to have its background removed.');
    await input().evaluate(n => n.setSelectionRange(7, 7));
    await input().press('@');
    await f().locator('#mention-options').getByRole('button', { name: '@Asset-2 · ABLO-002', exact: true }).click();
    assert.equal(await input().inputValue(), 'I want @Asset-2 to have its background removed.');
    assert.equal(await f().locator('.source-chip').count(), 2);
    pass('Referencing an already attached image keeps the other attachment available');
    await input().press('ControlOrMeta+z');
    assert.equal(await input().inputValue(), 'I want @ to have its background removed.');
    await input().press('ControlOrMeta+Shift+z');
    assert.equal(await input().inputValue(), 'I want @Asset-2 to have its background removed.');
    pass('Native undo and redo preserve inline insertion');
    await f().locator('.source-chip').first().getByRole('button', { name: 'Clear selection', exact: true }).click();
    assert.match(await input().inputValue(), /@Asset-2/);
    await f().locator('.source-reference').click();
    assert.equal((await input().inputValue()).match(/@Asset-2/g).length, 2);
    await f().locator('.source-chip').getByRole('button', { name: 'Clear selection', exact: true }).click();
    assert(!/@Asset-/.test(await input().inputValue()));
    await input().fill('Try '); await input().press('@'); await pick([3]);
    assert.match(await input().inputValue(), /@Asset-3/);
    pass('Removing an attachment removes its mentions; new products never inherit removed reference numbers');
    await input().fill('Contact support@example.test');
    await input().press('End'); await input().press('@');
    assert(await f().locator('#picker-dialog').isHidden());
    for (const text of ['Edit @Asset-99', 'Edit @Asset-', 'Edit @Asset-3wrong']) {
        await input().fill(text); assert(await f().locator('#send').isDisabled()); assert(await f().locator('#mention-error').isVisible());
    }
    await input().fill('Edit @Asset-3'); assert(await f().locator('#send').isEnabled());
    await page.reload(); await input().waitFor();
    assert.equal(await input().inputValue(), 'Edit @Asset-3');
    assert.match(await f().locator('.source-chip').innerText(), /@Asset-3 · ABLO-003/);
    pass('Unknown references are blocked, email typing is unaffected, and draft bindings survive refresh');
    const long = ('Keep @Asset-3 unchanged with soft lighting. ').repeat(20);
    for (const [width, height, dark] of [[1440, 1000, false], [1440, 1000, true], [390, 844, false], [390, 844, true]]) {
        await page.setViewportSize({ width, height });
        await page.evaluate(d => document.documentElement.classList.toggle('dark', d), dark);
        await input().fill(long); await input().press('ControlOrMeta+End');
        await page.waitForTimeout(150);
        assert(await f().locator('body').evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1));
        const metrics = await input().evaluate(n => {
            const m = document.getElementById('message-highlight'), a = getComputedStyle(n), b = getComputedStyle(m);
            return { text: n.scrollHeight, mirror: m.scrollHeight, top: n.scrollTop, mirrorTop: m.scrollTop, font: a.font, mirrorFont: b.font, width: n.clientWidth, mirrorWidth: m.clientWidth };
        });
        assert.equal(metrics.font, metrics.mirrorFont); assert.equal(metrics.width, metrics.mirrorWidth);
        assert(Math.abs(metrics.text - metrics.mirror) <= 2, JSON.stringify(metrics));
        assert(Math.abs(metrics.top - metrics.mirrorTop) <= 1, JSON.stringify(metrics));
        await input().fill('I want @Asset-3 to have its background removed.');
        await page.screenshot({ path: `${out}/inline-${width}-${dark ? 'dark' : 'light'}.png` });
    }
    pass('Highlight wrapping and scroll match native text at actual 390px and desktop widths in light and dark themes');
    await page.setViewportSize({ width: 1440, height: 1000 });
    await f().getByRole('button', { name: 'Collapse editor', exact: true }).click();
    await page.waitForTimeout(200);
    assert.match(await input().inputValue(), /@Asset-3/);
    await page.screenshot({ path: out + '/inline-docked.png' });
    await f().getByRole('button', { name: 'Expand editor', exact: true }).click();
    pass('Dock and expand preserve inline references');
    await f().getByRole('button', { name: 'New conversation', exact: true }).click();
    await input().press('@'); await pick([1, 2]);
    const single = await send('Give only @Asset-2 a blue background.');
    assert.equal(single.data.workflow_ids.length, 1); assert.equal(single.input.images.length, 2);
    await ready(1); assert.match(await f().locator('.result').innerText(), /ABLO-002/); assert(!/ABLO-001/.test(await f().locator('.result').innerText()));
    assert.equal(await f().locator('.user-message .image-reference').innerText(), '@Asset-2');
    await f().locator('[data-retry]').click();
    assert(await f().locator('#send').isEnabled());
    const retry = await send(await input().inputValue());
    assert.equal(retry.input.retry_result, single.data.workflow_ids[0]); await ready(2);
    pass('Mentioning one of two attached images targets only that product; retry keeps its original source and reference');
    await f().locator('[data-retry]').first().click();
    await f().locator('.source-chip').getByRole('button', { name: 'Clear selection', exact: true }).click();
    assert(!/@Asset-/.test(await input().inputValue()));
    assert(await f().locator('#mention-error').isHidden());
    pass('Clearing the retry source also clears its references');
    await f().getByRole('button', { name: 'New conversation', exact: true }).click();
    await input().press('@'); await pick([1, 2]);
    const title = 'Inline reference test ' + Date.now();
    const batch = await send(title + ': use blue for @Asset-1 and white for @Asset-2.');
    assert.equal(batch.data.workflow_ids.length, 2); await ready(2);
    const storageState = await context.storageState(); await context.close();
    context = await browser.newContext({ storageState, viewport: { width: 1440, height: 1000 } }); await attach();
    await page.goto(base + '/admin/dreamlayer/choose');
    await f().getByRole('button', { name: 'History', exact: true }).click();
    await f().locator('.thread-open').filter({ hasText: title }).click(); await ready(2);
    assert.deepEqual(await f().locator('.result').evaluateAll(nodes => nodes.map(n => n.dataset.workflow)), batch.data.workflow_ids);
    assert.deepEqual(await f().locator('.user-message .image-reference').allTextContents(), ['@Asset-1', '@Asset-2']);
    assert.equal(await f().getByText(/Some image requests were made with saved History off/).count(), 0);
    await input().press('@'); await pick([3]);
    assert.match(await input().inputValue(), /@Asset-3/);
    pass('Fresh context restores both batch results and inline message references, then allocates a new reference without collision');
    assert.deepEqual(errors, []);
    fs.writeFileSync(out + '/results.json', JSON.stringify({ checks, errors, mode: 'Real isolated host, recorded provider responses; no paid requests', single, retry, batch }, (key, value) => key === 'token' ? '[redacted]' : value, 2));
})().catch(async e => { console.error(e); await page?.screenshot({ path: out + '/failure.png' }).catch(() => {}); process.exitCode = 1; }).finally(async () => { await browser?.close(); });
